from collections import Counter
pedacos = [list("caixa"), list("baixa"), list("caixote")]
for rodada in range(3):
    pares = Counter()
    for p in pedacos:
        pares.update(zip(p, p[1:]))
    a, b = pares.most_common(1)[0][0]
    for p in pedacos:
        i = 0
        while i < len(p) - 1:
            if p[i] == a and p[i + 1] == b:
                p[i:i + 2] = [a + b]
            i += 1
    print(a + b, pedacos)

import numpy as np
v = {"gato": np.array([0.9, 0.8, 0.1]), "cachorro": np.array([0.8, 0.9, 0.2]), "carro": np.array([0.1, 0.2, 0.9])}
def cosseno(a, b):
    return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))
print(round(cosseno(v["gato"], v["cachorro"]), 2), round(cosseno(v["gato"], v["carro"]), 2))
